function Start-DesktopForAccount($a){try{$userData=[IO.Path]::GetFullPath([string]$a.UserData);if([string]::IsNullOrWhiteSpace($userData)){throw "账号 $($a.Key) 未配置 UserData"};$exe='C:\Program Files\WindowsApps\OpenAI.Codex_26.1027.3384.0_x64__2p2nqsd0c76g0\app\ChatGPT.exe';if(-not(Test-Path -LiteralPath $exe)){throw '未找到正式版 ChatGPT.exe'};if(-not(Test-Path -LiteralPath $userData)){New-Item -ItemType Directory -Force -LiteralPath $userData|Out-Null};$existing=@(Get-CimInstance Win32_Process -Filter "Name='ChatGPT.exe'" -ErrorAction SilentlyContinue|Where-Object {$_.CommandLine -and $_.CommandLine.IndexOf('--user-data-dir=',[StringComparison]::OrdinalIgnoreCase)-ge0 -and $_.CommandLine.IndexOf($userData,[StringComparison]::OrdinalIgnoreCase)-ge0});if($existing.Count -gt 0){try{$shell=New-Object -ComObject WScript.Shell;[void]$shell.AppActivate([int]$existing[0].ProcessId)}catch{};SetStatus "$($a.Key) Desktop 已经运行，已激活窗口，PID=$($existing[0].ProcessId)，UserData=$userData；登录状态请在 Desktop 中确认";Log $a.Key "Desktop already running and activated pid=$($existing[0].ProcessId) userData=$userData";return};$si=[Diagnostics.ProcessStartInfo]::new();$si.FileName=$exe;$si.UseShellExecute=$true;$si.Arguments='--user-data-dir="'+$userData.Replace('"','\"')+'"';$p=[Diagnostics.Process]::new();$p.StartInfo=$si;[void]$p.Start();Start-Sleep -Milliseconds 1000;$check=@(Get-CimInstance Win32_Process -Filter "Name='ChatGPT.exe'" -ErrorAction SilentlyContinue|Where-Object {$_.CommandLine -and $_.CommandLine.IndexOf('--user-data-dir=',[StringComparison]::OrdinalIgnoreCase)-ge0 -and $_.CommandLine.IndexOf($userData,[StringComparison]::OrdinalIgnoreCase)-ge0});if($check.Count -eq 0){throw 'Desktop 已启动但未能确认 UserData'};SetStatus "$($a.Key) Desktop 已启动，PID=$($check[0].ProcessId)，UserData=$userData；如未登录请在 Desktop 中完成首次登录";Log $a.Key "Desktop launch success pid=$($check[0].ProcessId) userData=$userData"}catch{SetStatus "$($a.Key) Desktop 启动失败：$($_.Exception.Message)" $true;Log $a.Key "Desktop launch failed: $($_.Exception.Message)"}}
