function Read-AccountConfig(){if(-not(Test-Path -LiteralPath $AccountConfig)){return @()};$raw=Get-Content -LiteralPath $AccountConfig -Raw|ConvertFrom-Json;$valueProp=$raw.PSObject.Properties['value'];if($null -ne $valueProp -and $null -ne $valueProp.Value){@($valueProp.Value)}else{@($raw)}}
function Save-AccountConfigUnsafe(){try{$disk=@(Read-AccountConfig);$byKey=@{};foreach($x in $disk){if($x.Key){$byKey[[string]$x.Key]=$x}};foreach($x in @($accounts)){if(-not $x.Key){continue};$key=[string]$x.Key;$o=$byKey[$key];if($o){if(-not [string]::IsNullOrWhiteSpace([string]$x.Email)){$o.Email=[string]$x.Email};if(-not [string]::IsNullOrWhiteSpace([string]$x.Plan)){$o.Plan=[string]$x.Plan};if(-not [string]::IsNullOrWhiteSpace([string]$x.CreatedAt)){$o.CreatedAt=[string]$x.CreatedAt};if($x.Home){$o.Home=[string]$x.Home};if($x.State){$o.State=[string]$x.State};if($x.UserData){$o.UserData=[string]$x.UserData}}else{$byKey[$key]=[pscustomobject]@{Key=$key;Email=[string]$x.Email;Plan=[string]$x.Plan;Home=[string]$x.Home;State=[string]$x.State;UserData=[string]$x.UserData;CreatedAt=[string]$x.CreatedAt}}};$merged=@($byKey.Values|Sort-Object {[string]$_.Key});New-Item -ItemType Directory -Force (Split-Path $AccountConfig)|Out-Null;$tmp=$AccountConfig+'.tmp-'+[guid]::NewGuid().ToString('N');$merged|Select-Object Key,Email,Plan,Home,State,UserData,CreatedAt|ConvertTo-Json -Depth 4|Set-Content -LiteralPath $tmp -Encoding UTF8;($merged|ConvertTo-Json -Depth 4)|ConvertFrom-Json|Out-Null;Move-Item -LiteralPath $tmp -Destination $AccountConfig -Force}catch{Log 'ALL' "账号配置保存失败：$($_.Exception.Message)";throw}}
function Save-AccountConfig([string]$AccountKey,[hashtable]$Updates,[string]$Operation='field-update',[hashtable]$Expected){$m=[Threading.Mutex]::new($false,$RegistryMutexName);if(-not$m.WaitOne(0)){throw 'Registry write conflict: another writer holds the lock'};$tmp=$null;try{$before=(Get-FileHash -LiteralPath $AccountConfig -Algorithm SHA256).Hash;$disk=@(Read-AccountConfig);$target=@($disk|Where-Object {[string]$_.Key -eq $AccountKey});if($target.Count -ne 1){throw "Cannot update ${AccountKey}: disk record count=$($target.Count)"};if($Expected){foreach($field in $Expected.Keys){if([string]$target[0].$field -cne [string]$Expected[$field]){throw "Registry conflict for $AccountKey field $field"}}};foreach($field in $Updates.Keys){if($field -notin @('Email','Plan','Home','State','UserData','CreatedAt')){throw "Unsupported field update: $field"};$target[0].$field=$Updates[$field]};$json=$disk|ConvertTo-Json -Depth 10;$json|ConvertFrom-Json|Out-Null;$tmp=$AccountConfig+'.tmp-'+[guid]::NewGuid().ToString('N');$json|Set-Content -LiteralPath $tmp -Encoding UTF8;Move-Item -LiteralPath $tmp -Destination $AccountConfig -Force;$tmp=$null;$after=(Get-FileHash -LiteralPath $AccountConfig -Algorithm SHA256).Hash;$check=@(Read-AccountConfig|Where-Object {[string]$_.Key -eq $AccountKey});if($check.Count -ne 1){throw "Post-write verification failed for $AccountKey"};foreach($field in $Updates.Keys){if([string]$check[0].$field -cne [string]$Updates[$field]){throw "Post-write field verification failed: $AccountKey.$field"}};Log 'REGISTRY' "source=GUI pid=$PID version=$ScriptVersion operation=$Operation account=$AccountKey time=$((Get-Date).ToString('o')) oldHash=$before newHash=$after result=success"}catch{if($tmp -and (Test-Path -LiteralPath $tmp)){Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue};Log 'REGISTRY' "source=GUI pid=$PID version=$ScriptVersion operation=$Operation account=$AccountKey result=conflict-or-failure message=$($_.Exception.Message)";throw}finally{$m.ReleaseMutex();$m.Dispose()} }
function Add-AccountConfigRecord([object]$NewRecord){$m=[Threading.Mutex]::new($false,$RegistryMutexName);if(-not$m.WaitOne(0)){throw 'Registry write conflict: another writer holds the lock'};$tmp=$null;try{$before=(Get-FileHash -LiteralPath $AccountConfig -Algorithm SHA256).Hash;$disk=@(Read-AccountConfig);if(@($disk|Where-Object {[string]$_.Key -eq [string]$NewRecord.Key}).Count){throw "Account already exists: $($NewRecord.Key)"};$json=(@($disk)+$NewRecord)|ConvertTo-Json -Depth 10;$json|ConvertFrom-Json|Out-Null;$tmp=$AccountConfig+'.tmp-'+[guid]::NewGuid().ToString('N');$json|Set-Content -LiteralPath $tmp -Encoding UTF8;Move-Item -LiteralPath $tmp -Destination $AccountConfig -Force;$tmp=$null;$after=(Get-FileHash -LiteralPath $AccountConfig -Algorithm SHA256).Hash;Log 'REGISTRY' "source=GUI pid=$PID version=$ScriptVersion operation=add account=$($NewRecord.Key) oldHash=$before newHash=$after result=success"}finally{if($tmp -and (Test-Path $tmp)){Remove-Item $tmp -Force -ErrorAction SilentlyContinue};$m.ReleaseMutex();$m.Dispose()}}
if(Test-Path -LiteralPath $AccountConfig){try{$saved=@(Read-AccountConfig);foreach($s in $saved){$match=@($accounts|Where-Object {[string]$_.Key -eq [string]$s.Key})|Select-Object -First 1;if($match){$match.Email=[string]$s.Email;$match.Plan=[string]$s.Plan;$match.Home=[string]$s.Home;$match.State=[string]$s.State;$match.UserData=[string]$s.UserData;$match.CreatedAt=[string]$s.CreatedAt}else{if($s.Key -and $s.Home -and $s.State){$accounts+=[pscustomobject]@{Key=[string]$s.Key;Email=[string]$s.Email;Plan=[string]$s.Plan;Home=[string]$s.Home;State=[string]$s.State;UserData=[string]$s.UserData;CreatedAt=[string]$s.CreatedAt}}}}}catch{$bad=$AccountConfig+'.corrupt-'+(Get-Date -Format 'yyyyMMdd-HHmmss');Copy-Item -LiteralPath $AccountConfig -Destination $bad -ErrorAction SilentlyContinue;Log 'ALL' "账号配置损坏，已备份到 $bad";throw "账号配置损坏，备份于 $bad"}}
