function SetStatus($s,$bad=$false){$status.Text="状态：$s";$status.Foreground=if($bad){[Windows.Media.Brushes]::DarkRed}else{[Windows.Media.Brushes]::DarkSlateGray}}
function Dt($s){if($null-eq$s){'—'}else{[DateTimeOffset]::FromUnixTimeSeconds([int64]$s).ToLocalTime().ToString('yyyy-MM-dd HH:mm:ss')}}
function Left($s){if($null-eq$s){'—'}$d=[DateTimeOffset]::FromUnixTimeSeconds([int64]$s)-[DateTimeOffset]::Now;if($d.TotalSeconds-le0){'已到期'}else{"{0}天 {1}小时 {2}分钟"-f [math]::Floor($d.TotalDays),$d.Hours,$d.Minutes}}
function Record-Error($stage,$accountKey,$ex){$line=if($ex.InvocationInfo.ScriptLineNumber){$ex.InvocationInfo.ScriptLineNumber}else{'?'};$source=if($ex.InvocationInfo.Line){$ex.InvocationInfo.Line.Trim()}else{'?'};Log $accountKey "ERROR stage=$stage line=$line type=$($ex.Exception.GetType().FullName) message=$($ex.Exception.Message) invocation=$source stack=$($ex.ScriptStackTrace) exception=$($ex.Exception.ToString())"}
function Get-QuotaScalar([object]$Value,[string]$Field,[string]$AccountKey){if($null-eq$Value){throw "$Field 缺失"};if($Value -is [Array]){Log $AccountKey "QUOTA_TYPE field=$Field type=$($Value.GetType().FullName) count=$($Value.Count) values=$([string]::Join(',',@($Value)))";if($Value.Count -ne 1){throw "$Field 是数组而非单个数值"};$Value=$Value[0]};if($Value -isnot [IConvertible]){throw "$Field 类型不是可转换数值：$($Value.GetType().FullName)"};[Convert]::ToDouble($Value,[Globalization.CultureInfo]::InvariantCulture)}
function Update-QuotaCard($a,$u,$result){$used=Get-QuotaScalar $result.PrimaryUsedPercent 'PrimaryUsedPercent' $a.Key;Log $a.Key "QUOTA_OPERAND field=PrimaryRemaining leftType=System.Double left=100 rightType=$($used.GetType().FullName) right=$used";$remaining=100.0-$used;$u.Email.Text="$($a.Key) · $($result.Email)";$u.Plan.Text="计划：$($result.Plan) · 成功读取：$($result.ReadAt)";$u.Status.Text='状态：正常';$u.Status.Foreground=[Windows.Media.Brushes]::DarkGreen;$u.Green.Width=New-Object Windows.GridLength($remaining,'Star');$u.Gray.Width=New-Object Windows.GridLength($used,'Star');$u.Remain.Text="剩余 $([int]$remaining)%    已使用 $([int]$used)%";$reset=[int64](Get-QuotaScalar $result.PrimaryResetsAt 'PrimaryResetsAt' $a.Key);$window=[int](Get-QuotaScalar $result.PrimaryWindowDurationMins 'PrimaryWindowDurationMins' $a.Key);$u.Reset.Text="主窗口：$window 分钟 · 重置 $(Dt $reset) · 倒计时 $(Left $reset)";if($result.HasSecondary){$su=Get-QuotaScalar $result.SecondaryUsedPercent 'SecondaryUsedPercent' $a.Key;Log $a.Key "QUOTA_OPERAND field=SecondaryRemaining leftType=System.Double left=100 rightType=$($su.GetType().FullName) right=$su";$sr=100.0-$su;$u.Second.Text="第二窗口：剩余 $([int]$sr)% · 已使用 $([int]$su)% · 重置 $(Dt ([int64](Get-QuotaScalar $result.SecondaryResetsAt 'SecondaryResetsAt' $a.Key)))"}else{$u.Second.Text='第二额度窗口：暂无'};$u.Credits.Text="Credits：hasCredits=$($result.CreditsHasCredits) · unlimited=$($result.CreditsUnlimited) · balance=$($result.CreditsBalance)";$u.Next.Text="下次自动刷新：$(Get-Date).AddMinutes([int]$interval.SelectedItem.Tag).ToString('yyyy-MM-dd HH:mm:ss')";Log $a.Key 'quota read succeeded'}
function StartRead($a){
 try { if($jobs.ContainsKey($a.Key)){return};$u=$ui[$a.Key];$u.Status.Text='状态：正在读取…';$u.Error.Text='';$lastRefresh[$a.Key]=Get-Date;if($TestFailKey -eq $a.Key){$jobs[$a.Key]=Start-Job -ScriptBlock {throw 'TEST_FAILURE: simulated account refresh failure'} -ErrorAction Stop}else{$jobs[$a.Key]=Start-Job -ScriptBlock $worker -ArgumentList (,$a) -ErrorAction Stop};SetStatus "$($a.Key) 正在读取" }
 catch { Record-Error 'StartRead' $a.Key $_; if($ui.ContainsKey($a.Key)){$ui[$a.Key].Status.Text='状态：读取失败（无旧数据）';$ui[$a.Key].Error.Text="错误：启动读取任务失败：$($_.Exception.Message)"};SetStatus "$($a.Key) 读取任务启动失败" $true }
}
function FinishRead($a,$j){
 try {
  $u=$ui[$a.Key];$errors=@();$r=@(Receive-Job -Job $j -ErrorAction SilentlyContinue -ErrorVariable errors);$state=$j.State;$reason=if($errors.Count){($errors|ForEach-Object{$_.Exception.Message}) -join '; '}else{$null};Remove-Job -Job $j -Force -ErrorAction SilentlyContinue;$jobs.Remove($a.Key)
   foreach($ev in @($r|Where-Object {$_.PSObject.Properties['Event'] -and $_.Event -eq 'rpc'})){Log $a.Key ("RPC stage=$($ev.Phase) id=$($ev.Id) method=$($ev.Method) status=$($ev.Status) at=$($ev.At) elapsedMs=$($ev.ElapsedMs)")}
   $result=$r|Where-Object{$_.PSObject.Properties['Ok']}|Select-Object -Last 1
   if($result -and $result.IdentityOk -and -not [string]::IsNullOrWhiteSpace([string]$result.Email)){$expected=@{Email=[string]$a.Email;Plan=[string]$a.Plan};Save-AccountConfig $a.Key @{Email=[string]$result.Email;Plan=[string]$result.Plan} 'identity-read' $expected;$a.Email=[string]$result.Email;$a.Plan=[string]$result.Plan;$u.Email.Text="$($a.Key) · $($result.Email)";$u.Plan.Text="计划：$($result.Plan) · 邮箱读取成功";if(-not $result.QuotaOk){$u.Status.Text='状态：邮箱正常，额度读取超时';$u.Status.Foreground=[Windows.Media.Brushes]::DarkOrange;$u.Error.Text="额度错误：$($result.Error)";$u.Next.Text='下次自动刷新：将继续尝试';Log $a.Key "identity succeeded; quota failed stage=$($result.ErrorStage)";return};Update-QuotaCard $a $u $result;return}
   else{$e=if($reason){$reason}elseif($result.Error){$result.Error}elseif($state -eq 'Failed'){'后台任务失败'}else{'读取失败'};$u.Status.Text='状态：读取失败（无旧数据）';$u.Status.Foreground=[Windows.Media.Brushes]::DarkRed;$u.Error.Text="错误：$e";$u.Next.Text='下次自动刷新：将继续尝试';Log $a.Key "quota read failed: $e"}
 } catch { Record-Error 'FinishRead' $a.Key $_;if($jobs.ContainsKey($a.Key)){$jobs.Remove($a.Key)};if($ui.ContainsKey($a.Key)){$ui[$a.Key].Status.Text='状态：读取失败（无旧数据）';$ui[$a.Key].Error.Text="错误：处理读取结果失败：$($_.Exception.Message)"} }
}
foreach($a in $accounts){$b=New-Object Windows.Controls.Border;$b.Background=[Windows.Media.Brushes]::White;$b.BorderBrush=[Windows.Media.Brushes]::LightGray;$b.BorderThickness=New-Object Windows.Thickness(1);$b.CornerRadius=New-Object Windows.CornerRadius(10);$b.Padding=New-Object Windows.Thickness(15);$b.Margin=New-Object Windows.Thickness(0,0,0,12);$sp=New-Object Windows.Controls.StackPanel;$head=New-Object Windows.Controls.DockPanel;$email=New-Object Windows.Controls.TextBlock;$email.Text="$($a.Key) · 邮箱读取中…";$email.FontSize=19;$email.FontWeight='SemiBold';$btn=New-Object Windows.Controls.Button;$btn.Content='刷新此账号';$btn.Padding=New-Object Windows.Thickness(12,5,12,5);[Windows.Controls.DockPanel]::SetDock($btn,'Right');$btn.Tag=$a;$head.Children.Add($btn)|Out-Null;$head.Children.Add($email)|Out-Null;$email.Tag=$a;$email.Cursor=[Windows.Input.Cursors]::Hand;$email.Add_MouseLeftButtonUp({param($sender,$eventArgs) DesktopButtonClick $sender $eventArgs});$sp.Children.Add($head)|Out-Null;$plan=New-Object Windows.Controls.TextBlock;$statusT=New-Object Windows.Controls.TextBlock;$plan.Text='计划：尚无数据';$statusT.Text='状态：尚无数据';$bar=New-Object Windows.Controls.Grid;$bar.Height=22;$bar.ColumnDefinitions.Add((New-Object Windows.Controls.ColumnDefinition));$bar.ColumnDefinitions.Add((New-Object Windows.Controls.ColumnDefinition));$bar.Background=[Windows.Media.Brushes]::LightGray;$green=New-Object Windows.Controls.Border;$green.Background=[Windows.Media.Brushes]::ForestGreen;$gray=New-Object Windows.Controls.Border;$gray.Background=[Windows.Media.Brushes]::LightGray;[Windows.Controls.Grid]::SetColumn($green,0);[Windows.Controls.Grid]::SetColumn($gray,1);$bar.Children.Add($green)|Out-Null;$bar.Children.Add($gray)|Out-Null;$remain=New-Object Windows.Controls.TextBlock;$reset=New-Object Windows.Controls.TextBlock;$second=New-Object Windows.Controls.TextBlock;$credits=New-Object Windows.Controls.TextBlock;$next=New-Object Windows.Controls.TextBlock;$err=New-Object Windows.Controls.TextBlock;$err.Foreground=[Windows.Media.Brushes]::DarkRed;foreach($z in @($plan,$statusT,$bar,$remain,$reset,$second,$credits,$next,$err)){$sp.Children.Add($z)|Out-Null};$b.Child=$sp;$cards.Children.Add($b)|Out-Null;$btn.Add_Click({StartRead $this.Tag});$desktopBtn=New-Object Windows.Controls.Button;$desktopBtn.Content='启动 Desktop';$desktopBtn.Padding=New-Object Windows.Thickness(12,5,12,5);$desktopBtn.Margin=New-Object Windows.Thickness(8,0,0,0);$desktopBtn.Tag=$a;[Windows.Controls.DockPanel]::SetDock($desktopBtn,'Right');$head.Children.Add($desktopBtn)|Out-Null;$desktopBtn.Add_Click({param($sender,$eventArgs) DesktopButtonClick $sender $eventArgs});$ui[$a.Key]=[pscustomobject]@{Email=$email;Plan=$plan;Status=$statusT;Green=$bar.ColumnDefinitions[0];Gray=$bar.ColumnDefinitions[1];Remain=$remain;Reset=$reset;Second=$second;Credits=$credits;Next=$next;Error=$err}}
$timer=New-Object Windows.Threading.DispatcherTimer;$timer.Add_Tick({try{if($accountTask -and $accountTask.HasExited){$accountTask=$null;$add.IsEnabled=$true;$reload.RaiseEvent((New-Object Windows.RoutedEventArgs([Windows.Controls.Button]::ClickEvent)));SetStatus '添加账号任务已完成'};foreach($a in $accounts){if($jobs.ContainsKey($a.Key)){$j=$jobs[$a.Key];if($j.State-in @('Completed','Failed','Stopped')){FinishRead $a $j}}elseif($lastRefresh.ContainsKey($a.Key) -and ((Get-Date)-$lastRefresh[$a.Key]).TotalMinutes -ge [int]$interval.SelectedItem.Tag){StartRead $a}}}catch{Record-Error 'DispatcherTimer.Tick' 'ALL' $_}});$timer.Start();$w.Add_ContentRendered({try{foreach($a in $accounts){StartRead $a}}catch{Record-Error 'ContentRendered' 'ALL' $_}});$w.Add_Closed({try{$timer.Stop();foreach($j in @($jobs.Values)){Stop-Job $j -EA SilentlyContinue;Remove-Job $j -Force -EA SilentlyContinue}}catch{Record-Error 'Window.Closed' 'ALL' $_}finally{$GuiMutex.ReleaseMutex();$GuiMutex.Dispose()}});if($SmokeTest){$w.Add_ContentRendered({$w.Dispatcher.BeginInvoke([action]{Start-Sleep -Milliseconds 800;$w.Close()})|Out-Null})};try{$w.ShowDialog()|Out-Null}catch{Record-Error 'ShowDialog' 'ALL' $_;throw}
$AddAccountHandler={try{$keys=@($accounts|ForEach-Object Key);$candidate=([char](65..90|Where-Object{$_ -notin @($keys|ForEach-Object{[int][char]$_})}|Select-Object -First 1));if(-not$candidate){throw '已达到 Z，暂不支持更多字母代号'};$key=[string]$candidate;$home=Join-Path $env:USERPROFILE ('.codex-account-'+$key.ToLower());$state=Join-Path $env:LOCALAPPDATA ('CodexAccountManager\QuotaState\'+$key);$ud=Join-Path $env:LOCALAPPDATA ('CodexAccountManager\'+$key+'\UserData');if(Test-Path $home){throw "目标 Home 已存在：$home"};New-Item -ItemType Directory -Force $home,$state,$ud|Out-Null;$new=[pscustomobject]@{Key=$key;Email=$null;Plan=$null;Home=$home;State=$state;UserData=$ud;CreatedAt=(Get-Date).ToString('o')};Add-AccountConfigRecord $new;$accounts+=$new;[Windows.MessageBox]::Show("已创建 $key 的独立 Home。请在该 Home 中运行官方 Codex 登录流程；登录完成后重新打开管理器以验证并加入卡片。","添加账号")|Out-Null}catch{Log 'ALL' "AddAccount failed: $($_.Exception.Message)";[Windows.MessageBox]::Show("添加账号失败：$($_.Exception.Message)",'添加账号失败')|Out-Null}}
